@@ -0,0 +1,31 @@
+// Sites: kitchens that share items, suppliers, recipes and dishes but keep
+// their own locations, batches and stock-takes (docs/DATA.md).
+import { AppError } from "../errors.js";
+
+/** The site a request belongs to when it names none. */
+export const DEFAULT_SITE = "main";
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** The ids of the locations at a site. */
+export function locationIds(store, site) {
+  return store.data.locations.filter((l) => l.site === site).map((l) => l.id);
+}
+
+/** Whether a location exists and belongs to `site` (any site when `site` is undefined). */
+export function inSite(store, locationId, site) {
+  const loc = store.data.locations.find((l) => l.id === locationId);
+  return !!loc && (site === undefined || loc.site === site);
+}
+
+/** The batches stored at `site` (all batches when `site` is undefined). */
+export function siteBatches(store, site) {
+  if (site === undefined) return store.data.batches;
+  const here = new Set(locationIds(store, site));
+  return store.data.batches.filter((b) => here.has(b.location));
+}
